import{_ as i,C as a,c as e,o as t,j as o,b as l,a0 as r,a as n,w as s,G as c,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Nutrizione per prestazioni di precisione","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/nutrition/index.md","filePath":"it/education/nutrition/index.md"}');const p=i({name:"it/education/nutrition/index.md"},[["render",function(i,u,p,m,g,h){const b=a("Mermaid");return t(),e("div",null,[u[2]||(u[2]=o("h1",{id:"nutrizione-per-prestazioni-di-precisione",tabindex:"-1"},[n("Nutrizione per prestazioni di precisione "),o("a",{class:"header-anchor",href:"#nutrizione-per-prestazioni-di-precisione","aria-label":'Permalink to "Nutrizione per prestazioni di precisione"'},"​")],-1)),u[3]||(u[3]=o("p",null,[n("La boccia è uno sport di precisione, non di resistenza. Le tue esigenze nutrizionali sono diverse da quelle di un maratoneta o di un calciatore. Ciò che conta di più è la "),o("strong",null,"stabilità del carburante per il cervello"),n(": mantenere la mente attiva e le mani ferme durante una lunga giornata di gara.")],-1)),u[4]||(u[4]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"La grande idea"),o("p",null,[o("strong",null,"Il tuo cervello è lo strumento più importante nel gioco delle bocce. Forniscigli carburante stabile, non energia da montagne russe."),n(" Concentrati su proteine, grassi sani e sull'idratazione. Evita i picchi di zucchero.")])],-1)),(t(),l(d,null,{default:s(()=>[c(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BZucchero%2FCarboidrati%20semplici%5D%20--%3E%20B%5Bpicco%20di%20zucchero%20nel%20sangue%5D%0A%20%20%20%20B%20--%3E%20C%5Brilascio%20di%20insulina%5D%0A%20%20%20%20C%20--%3E%20D%5BCrollo%20della%20glicemia%5D%0A%20%20%20%20D%20--%3E%20E%5BRisposta%20all%26%2339%3Badrenalina%5D%0A%20%20%20%20E%20--%3E%20F%5BTremori%20e%20ansia%5D%0A%0A%20%20%20%20G%5BProteine%20e%20grassi%20sani%5D%20--%3E%20H%5BGlicemia%20stabile%5D%0A%20%20%20%20H%20--%3E%20I%5BEnergia%20costante%5D%0A%20%20%20%20I%20--%3E%20J%5BMessa%20a%20fuoco%20nitida%5D%0A%20%20%20%20J%20--%3E%20K%5BMani%20ferme%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:s(()=>[...u[0]||(u[0]=[n(" Loading... ",-1)])]),_:1})),u[5]||(u[5]=r('<h2 id="la-sfida-dell-39-atleta-di-precisione" tabindex="-1">La sfida dell&#39;atleta di precisione <a class="header-anchor" href="#la-sfida-dell-39-atleta-di-precisione" aria-label="Permalink to &quot;La sfida dell&amp;#39;atleta di precisione&quot;">​</a></h2><p>A differenza degli sport ad alta intensità, la pétanque non richiede grandi riserve di glicogeno o un rapido reintegro energetico. Ciò che richiede è:</p><ul><li><strong>Glicemia stabile</strong> - senza picchi o crolli</li><li><strong>Chiarezza mentale costante</strong> - concentrazione che dura tutto il giorno</li><li><strong>Mani ferme</strong> - niente tremori o scosse</li><li><strong>Calma i nervi</strong> - bassa risposta all&#39;ansia e allo stress</li></ul><p>La tua strategia nutrizionale dovrebbe essere ottimizzata in base a questi fattori e non in base alla produzione di energia pura.</p><h2 id="il-problema-con-lo-zucchero-e-i-carboidrati-semplici" tabindex="-1">Il problema con lo zucchero e i carboidrati semplici <a class="header-anchor" href="#il-problema-con-lo-zucchero-e-i-carboidrati-semplici" aria-label="Permalink to &quot;Il problema con lo zucchero e i carboidrati semplici&quot;">​</a></h2><p>Molti atleti optano per diete ricche di carboidrati. Per i giocatori di pétanque, questo può effettivamente compromettere le prestazioni.</p><h3 id="le-montagne-russe-della-glicemia" tabindex="-1">Le montagne russe della glicemia <a class="header-anchor" href="#le-montagne-russe-della-glicemia" aria-label="Permalink to &quot;Le montagne russe della glicemia&quot;">​</a></h3><p>Quando mangi zucchero o carboidrati semplici:</p><ol><li>La glicemia aumenta rapidamente</li><li>L&#39;insulina viene rilasciata per abbassarlo</li><li>Crollo della glicemia (ipoglicemia)</li><li>Il tuo corpo rilascia adrenalina per compensare</li><li>Si avvertono tremori, ansia e scarsa concentrazione</li></ol><p><strong>Questo è l&#39;opposto di ciò di cui hai bisogno per la precisione.</strong></p><h3 id="sintomi-di-instabilita-della-glicemia" tabindex="-1">Sintomi di instabilità della glicemia <a class="header-anchor" href="#sintomi-di-instabilita-della-glicemia" aria-label="Permalink to &quot;Sintomi di instabilità della glicemia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sintomo</th><th>Impatto sulle prestazioni</th></tr></thead><tbody><tr><td>Mani tremanti</td><td>Rilascio incoerente</td></tr><tr><td>Difficoltà di concentrazione</td><td>Scarsa capacità decisionale</td></tr><tr><td>Irritabilità</td><td>Conflitto di squadra, scarsa compostezza</td></tr><tr><td>Stanchezza dopo i pasti</td><td>Crollo pomeridiano</td></tr><tr><td>Ansia</td><td>Sensibilità alla pressione</td></tr><tr><td>Nebbia cerebrale</td><td>Pensiero tattico lento</td></tr></tbody></table><h2 id="un-approccio-migliore-energia-stabile" tabindex="-1">Un approccio migliore: energia stabile <a class="header-anchor" href="#un-approccio-migliore-energia-stabile" aria-label="Permalink to &quot;Un approccio migliore: energia stabile&quot;">​</a></h2><p>L&#39;obiettivo è fornire al cervello un carburante costante, senza le montagne russe.</p><h3 id="principi-chiave" tabindex="-1">Principi chiave <a class="header-anchor" href="#principi-chiave" aria-label="Permalink to &quot;Principi chiave&quot;">​</a></h3><ol><li><strong>Dai priorità alle proteine e ai grassi sani</strong> - Forniscono energia lenta e costante</li><li><strong>Scegli carboidrati complessi invece di quelli semplici</strong> - Se mangi carboidrati, scegli quelli che si digeriscono lentamente</li><li><strong>Evitare i picchi di zucchero</strong> - Soprattutto prima e durante la competizione</li><li><strong>Mantieniti idratato</strong> - La disidratazione influisce significativamente sulla concentrazione</li><li><strong>Mangia regolarmente</strong> - Non lasciarti prendere dalla fame</li></ol><h3 id="alimenti-che-aiutano" tabindex="-1">Alimenti che aiutano <a class="header-anchor" href="#alimenti-che-aiutano" aria-label="Permalink to &quot;Alimenti che aiutano&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo di cibo</th><th>Esempi</th><th>Perché funziona</th></tr></thead><tbody><tr><td>Proteina</td><td>Uova, noci, formaggio, carne</td><td>Digestione lenta, energia stabile</td></tr><tr><td>Grassi sani</td><td>Avocado, olio d&#39;oliva, noci</td><td>Carburante di lunga durata</td></tr><tr><td>Carboidrati complessi</td><td>Verdure, legumi</td><td>La fibra rallenta l&#39;assorbimento</td></tr><tr><td>Frutta a basso contenuto di zucchero</td><td>Bacche, mele</td><td>Nutrienti senza spike</td></tr></tbody></table><h3 id="cibi-da-limitare" tabindex="-1">Cibi da limitare <a class="header-anchor" href="#cibi-da-limitare" aria-label="Permalink to &quot;Cibi da limitare&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo di cibo</th><th>Esempi</th><th>Perché è problematico</th></tr></thead><tbody><tr><td>Zucchero</td><td>Caramelle, bibite, pasticcini</td><td>Picco e crollo rapidi</td></tr><tr><td>Pane/pasta bianca</td><td>Panini, piatti di pasta</td><td>Conversione rapida in zucchero</td></tr><tr><td>Succo di frutta</td><td>Succo d&#39;arancia, frullati</td><td>Zucchero concentrato</td></tr><tr><td>Bevande energetiche</td><td>La maggior parte dei marchi commerciali</td><td>Crollo di zucchero + caffeina</td></tr></tbody></table><h2 id="nutrizione-per-il-giorno-della-gara" tabindex="-1">Nutrizione per il giorno della gara <a class="header-anchor" href="#nutrizione-per-il-giorno-della-gara" aria-label="Permalink to &quot;Nutrizione per il giorno della gara&quot;">​</a></h2><h3 id="prima-della-competizione" tabindex="-1">Prima della competizione <a class="header-anchor" href="#prima-della-competizione" aria-label="Permalink to &quot;Prima della competizione&quot;">​</a></h3><p><strong>2-3 ore prima:</strong></p><ul><li>Pasto equilibrato con proteine, grassi e verdure</li><li>Evitare i carboidrati pesanti che potrebbero causare sonnolenza</li><li>Esempio: Uova con verdure o insalata con pollo</li></ul><p><strong>1 ora prima:</strong></p><ul><li>Spuntino leggero se necessario</li><li>Noci, formaggio o una piccola porzione di proteine</li><li>Evita tutto ciò che è zuccherato</li></ul><h3 id="durante-la-competizione" tabindex="-1">Durante la competizione <a class="header-anchor" href="#durante-la-competizione" aria-label="Permalink to &quot;Durante la competizione&quot;">​</a></h3><p><strong>Tra le partite:</strong></p><ul><li>Acqua (la più importante)</li><li>Piccoli spuntini proteici (noci, formaggio, carne)</li><li>Evitare snack e bevande zuccherate</li></ul><p><strong>Segnali che indicano che devi mangiare:</strong></p><ul><li>Difficoltà di concentrazione</li><li>Irritabilità</li><li>Mi sento tremante</li><li>Mal di testa</li></ul><h3 id="dopo-la-competizione" tabindex="-1">Dopo la competizione <a class="header-anchor" href="#dopo-la-competizione" aria-label="Permalink to &quot;Dopo la competizione&quot;">​</a></h3><ul><li>Rifornisciti con un pasto equilibrato</li><li>Reidratarsi completamente</li><li>Non &quot;premiarti&quot; con lo zucchero: influenzerà la tua guarigione</li></ul><h2 id="idratazione" tabindex="-1">Idratazione <a class="header-anchor" href="#idratazione" aria-label="Permalink to &quot;Idratazione&quot;">​</a></h2><p>La disidratazione influisce sulle funzioni cognitive prima ancora di avvertire la sete.</p><h3 id="linee-guida" tabindex="-1">Linee guida <a class="header-anchor" href="#linee-guida" aria-label="Permalink to &quot;Linee guida&quot;">​</a></h3><ul><li><strong>Inizia idratato</strong> - Bevi acqua durante il giorno prima della gara</li><li><strong>Durante il gioco</strong> - Sorseggia acqua regolarmente, non aspettare di avere sete</li><li><strong>Evitare l&#39;eccesso di caffeina</strong> - È un diuretico</li><li><strong>Fai attenzione ai segnali</strong> - Mal di testa, urine scure, stanchezza</li></ul><h3 id="quanto" tabindex="-1">Quanto? <a class="header-anchor" href="#quanto" aria-label="Permalink to &quot;Quanto?&quot;">​</a></h3><p>Una regola generale: cerca di ottenere un&#39;urina di colore giallo chiaro. Se è scura, hai bisogno di più acqua.</p><h2 id="l-39-opzione-a-basso-contenuto-di-carboidrati" tabindex="-1">L&#39;opzione a basso contenuto di carboidrati <a class="header-anchor" href="#l-39-opzione-a-basso-contenuto-di-carboidrati" aria-label="Permalink to &quot;L&amp;#39;opzione a basso contenuto di carboidrati&quot;">​</a></h2><p>Alcuni atleti di precisione adottano diete a basso contenuto di carboidrati o chetogeniche. La teoria:</p><p><strong>Potenziali benefici:</strong></p><ul><li>Glicemia molto stabile (nessun picco possibile)</li><li>Chiarezza mentale costante</li><li>Riduzione dell&#39;ansia e dei tremori</li><li>Nessun crollo energetico pomeridiano</li></ul><p><strong>Considerazioni:</strong></p><ul><li>Richiede un periodo di adattamento (1-2 settimane)</li><li>Non adatto a tutti</li><li>Richiede pianificazione e impegno</li><li>Consultare prima un medico</li></ul><p>Si tratta di una strategia avanzata, non necessaria per tutti, ma che vale la pena prendere in considerazione se la stabilità della glicemia rappresenta un problema significativo per te.</p><h2 id="cibo-come-pratica-allenare-il-corpo" tabindex="-1">Cibo come pratica: allenare il corpo <a class="header-anchor" href="#cibo-come-pratica-allenare-il-corpo" aria-label="Permalink to &quot;Cibo come pratica: allenare il corpo&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Concetto critico</p><p><strong>Il cibo non è solo carburante, è qualcosa con cui ti alleni.</strong> Proprio come ti alleni per il lancio, devi allenare la tua alimentazione per far sì che il tuo corpo si senta a suo agio con l&#39;alimentazione del giorno della gara.</p></div><h3 id="perche-la-pratica-alimentare-e-importante" tabindex="-1">Perché la pratica alimentare è importante <a class="header-anchor" href="#perche-la-pratica-alimentare-e-importante" aria-label="Permalink to &quot;Perché la pratica alimentare è importante&quot;">​</a></h3><p>Il tuo sistema digestivo è allenabile. Ciò che mangi regolarmente diventa ciò che il tuo corpo si aspetta e gestisce meglio. Se mangi solo proteine e verdure nei giorni di gara, il tuo corpo non si adatterà.</p><p><strong>Il problema:</strong></p><ul><li>Mangiare cibi non familiari il giorno della gara può causare disturbi digestivi</li><li>Il tuo corpo ha bisogno di tempo per adattarsi alle nuove abitudini alimentari</li><li>Stress + cibo sconosciuto = potenziali problemi di stomaco</li><li>L&#39;ansia da prestazione è già abbastanza grave senza aggiungere l&#39;ansia digestiva</li></ul><p><strong>La soluzione:</strong></p><ul><li>Metti in pratica la tua alimentazione da competizione durante l&#39;allenamento</li><li>Rendi i tuoi cibi preferiti per il giorno della gara parte della tua routine quotidiana</li><li>Allena il tuo corpo ad abituarsi ad alimenti con energia stabile</li></ul><h3 id="il-processo-di-adattamento" tabindex="-1">Il processo di adattamento <a class="header-anchor" href="#il-processo-di-adattamento" aria-label="Permalink to &quot;Il processo di adattamento&quot;">​</a></h3>',55)),(t(),l(d,null,{default:s(()=>[c(b,{id:"mermaid-586",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDieta%20attuale%5D%20--%3E%20B%5BCambiamenti%20graduali%5D%0A%20%20%20%20B%20--%3E%20C%5BAdattamento%20del%20corpo%20%3Cbr%2F%3E%202-4%20settimane%5D%0A%20%20%20%20C%20--%3E%20D%5BNuova%20normalit%C3%A0%5D%0A%20%20%20%20D%20--%3E%20E%5BPronto%20per%20la%20competizione%5D%0A%0A%20%20%20%20F%5BCambiamento%20improvviso%20%3Cbr%2F%3E%20Giorno%20della%20competizione%5D%20--%3E%20G%5BDisturbi%20digestivi%5D%0A%20%20%20%20G%20--%3E%20H%5BScarsa%20prestazione%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:s(()=>[...u[1]||(u[1]=[n(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=r('<p>Quando cambi la tua dieta:</p><ol><li><strong>Settimana 1-2:</strong> Il tuo corpo si adatta ai nuovi alimenti, potrebbe avere sensazioni diverse</li><li><strong>Settimana 3-4:</strong> Avviene l&#39;adattamento, i nuovi alimenti sembrano normali</li><li><strong>Settimana 5+:</strong> Il tuo corpo è a suo agio ed efficiente con questi alimenti</li></ol><p><strong>Ecco perché non puoi semplicemente &quot;mangiare sano&quot; il giorno della gara e aspettarti risultati ottimali.</strong></p><h3 id="come-praticare-la-tua-nutrizione" tabindex="-1">Come praticare la tua nutrizione <a class="header-anchor" href="#come-praticare-la-tua-nutrizione" aria-label="Permalink to &quot;Come praticare la tua nutrizione&quot;">​</a></h3><h4 id="_1-inizia-durante-l-39-allenamento" tabindex="-1">1. Inizia durante l&#39;allenamento <a class="header-anchor" href="#_1-inizia-durante-l-39-allenamento" aria-label="Permalink to &quot;1. Inizia durante l&amp;#39;allenamento&quot;">​</a></h4><p><strong>Esercitati a mangiare come ti aspetti in gara durante le sessioni di allenamento:</strong></p><ul><li>Mangia lo stesso pasto pre-allenamento che mangeresti prima di una gara</li><li>Porta gli stessi snack che porteresti a un torneo</li><li>Nota come risponde il tuo corpo</li><li>Adatta in base a ciò che funziona</li></ul><p><strong>Esempio di giornata di formazione:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-rendila-la-tua-normalita" tabindex="-1">2. Rendila la tua normalità <a class="header-anchor" href="#_2-rendila-la-tua-normalita" aria-label="Permalink to &quot;2. Rendila la tua normalità&quot;">​</a></h4><p><strong>Non seguire una &quot;dieta da competizione&quot; e una &quot;dieta normale&quot;</strong> - questo crea due problemi:</p><ul><li>Il tuo corpo non si adatta mai completamente a nessuno dei due</li><li>Il cibo da competizione sembra insolito e stressante</li></ul><p><strong>Invece:</strong></p><ul><li>Rendi gli alimenti a energia stabile la tua norma quotidiana</li><li>Il tuo corpo diventa efficiente nell&#39;utilizzare proteine e grassi</li><li>Il giorno della gara sembra normale, non diverso</li><li>Nessuna sorpresa digestiva</li></ul><h4 id="_3-testare-e-perfezionare" tabindex="-1">3. Testare e perfezionare <a class="header-anchor" href="#_3-testare-e-perfezionare" aria-label="Permalink to &quot;3. Testare e perfezionare&quot;">​</a></h4><p><strong>Utilizzare l&#39;addestramento per sperimentare:</strong></p><table tabindex="0"><thead><tr><th>Test</th><th>Cosa notare</th><th>Regolare</th></tr></thead><tbody><tr><td>Orario dei pasti prima dell&#39;allenamento</td><td>Livelli di energia, concentrazione</td><td>Trova la tua finestra ottimale</td></tr><tr><td>Diverse fonti proteiche</td><td>Digestione, conforto</td><td>Identifica cosa funziona meglio</td></tr><tr><td>Tipi di snack</td><td>Energia sostenuta</td><td>Trova i tuoi snack preferiti</td></tr><tr><td>Quantità di idratazione</td><td>Concentrazione, pause bagno</td><td>Assunzione di equilibrio</td></tr></tbody></table><p><strong>Tieni un registro semplice:</strong></p><ul><li>Cosa hai mangiato e quando</li><li>Come ti sei sentito durante l&#39;allenamento</li><li>Livelli di energia e concentrazione</li><li>Eventuali problemi digestivi</li></ul><h4 id="_4-costruisci-comfort-e-sicurezza" tabindex="-1">4. Costruisci comfort e sicurezza <a class="header-anchor" href="#_4-costruisci-comfort-e-sicurezza" aria-label="Permalink to &quot;4. Costruisci comfort e sicurezza&quot;">​</a></h4><p><strong>Il beneficio psicologico:</strong></p><p>Quando hai messo in pratica la tua alimentazione centinaia di volte durante l&#39;allenamento:</p><ul><li>Sai esattamente come risponderà il tuo corpo</li><li>Nessuna ansia per le scelte alimentari</li><li>Una cosa in meno di cui preoccuparsi il giorno della gara</li><li>Fiducia nella tua preparazione</li></ul><p><strong>Questo è lo stesso principio dell&#39;allenamento al lancio</strong>: la ripetizione aumenta il comfort e l&#39;affidabilità.</p><h3 id="sfide-comuni-di-adattamento" tabindex="-1">Sfide comuni di adattamento <a class="header-anchor" href="#sfide-comuni-di-adattamento" aria-label="Permalink to &quot;Sfide comuni di adattamento&quot;">​</a></h3><details class="details custom-block"><summary>Passaggio da una dieta ricca di carboidrati a una dieta a energia stabile</summary><p><strong>Sfida:</strong> Sei abituato a pane, pasta e snack zuccherati</p><p><strong>Periodo di adattamento:</strong> 2-4 settimane</p><p><strong>Cosa aspettarsi:</strong></p><ul><li>Settimana 1: Potrebbe sembrare diverso, desiderio di cibi vecchi</li><li>Settimana 2: L&#39;energia si stabilizza, le voglie si riducono</li><li>Settimana 3-4: Nuova normalità, corpo efficiente con grassi/proteine</li></ul><p><strong>Come esercitarsi:</strong></p><ul><li>Inizia con un pasto alla volta</li><li>Sostituisci prima i carboidrati semplici con carboidrati complessi</li><li>Aumentare gradualmente le proteine e i grassi sani</li><li>Esercitati prima durante l&#39;allenamento a basso rischio</li></ul></details><details class="details custom-block"><summary>Trovare gli alimenti che funzionano per te</summary><p><strong>Sfida:</strong> Non tutti digeriscono bene gli stessi alimenti</p><p><strong>Cosa testare:</strong></p><ul><li>Diverse fonti proteiche (uova vs. carne vs. noci)</li><li>Orario dei pasti (2 ore prima vs. 3 ore prima)</li><li>Porzioni (troppo = pigrizia, troppo poco = fame)</li><li>Alimenti specifici che causano disagio</li></ul><p><strong>Approccio pratico:</strong></p><ul><li>Prova una variabile alla volta</li><li>Fornire a ciascun test 2-3 sessioni di allenamento</li><li>Nota cosa ti fa sentire meglio</li><li>Crea il tuo &quot;menu di gara&quot; personale</li></ul></details><details class="details custom-block"><summary>Come gestire gli ambienti alimentari dei tornei</summary><p><strong>Sfida:</strong> I tornei spesso hanno opzioni alimentari limitate</p><p><strong>Soluzione pratica:</strong></p><ul><li>Porta sempre con te i tuoi spuntini (mettilo in pratica)</li><li>Individuare i luoghi in anticipo, quando possibile</li><li>Avere opzioni di backup che sai funzionare</li><li>Esercitati a mangiare in ambienti diversi</li></ul><p><strong>Preparazione mentale:</strong></p><ul><li>Non fare affidamento sul cibo del locale</li><li>Considera il cibo come parte della tua attrezzatura</li><li>Imballalo come imballi le tue palle</li></ul></details><h3 id="il-piano-di-pratica-nutrizionale-di-30-giorni" tabindex="-1">Il piano di pratica nutrizionale di 30 giorni <a class="header-anchor" href="#il-piano-di-pratica-nutrizionale-di-30-giorni" aria-label="Permalink to &quot;Il piano di pratica nutrizionale di 30 giorni&quot;">​</a></h3><p><strong>Obiettivo:</strong> Rendere l&#39;alimentazione a energia stabile la tua normalità confortevole</p><p><strong>Settimana 1-2: Fondazione</strong></p><ul><li>Sostituisci un pasto al giorno con un&#39;alimentazione in stile competizione</li><li>Praticare l&#39;alimentazione pre-allenamento</li><li>Inizia a portare degli spuntini all&#39;allenamento</li><li>Nota come risponde il tuo corpo</li></ul><p><strong>Settimana 3-4: Espansione</strong></p><ul><li>Prepara due pasti al giorno a base di energia stabile</li><li>Praticare un&#39;alimentazione completa nei giorni di gara nei giorni di allenamento</li><li>Affina le tue scelte di snack</li><li>Crea la tua lista di cibi preferiti</li></ul><p><strong>Settimana 5+: Padronanza</strong></p><ul><li>Mangiare a energia stabile è la tua nuova normalità</li><li>Il corpo è completamente adattato</li><li>Il giorno della gara sembra una routine</li><li>Fiducia nella tua alimentazione</li></ul><h3 id="il-tuo-kit-alimentare-per-la-competizione" tabindex="-1">Il tuo kit alimentare per la competizione <a class="header-anchor" href="#il-tuo-kit-alimentare-per-la-competizione" aria-label="Permalink to &quot;Il tuo kit alimentare per la competizione&quot;">​</a></h3><p><strong>Esercitati a portare questo bagaglio per ogni sessione di allenamento:</strong></p><p><strong>Pre-gara (2-3 ore prima):</strong></p><ul><li>[ ] Fonte proteica (uova, carne o noci)</li><li>[ ] Verdure o insalata</li><li>[ ] Grassi sani (avocado, olio d&#39;oliva, formaggio)</li></ul><p><strong>Durante la competizione:</strong></p><ul><li>[ ] Bottiglia d&#39;acqua (ricaricabile)</li><li>[ ] Frutta secca mista (piccole porzioni)</li><li>[ ] Uova sode (se riesci a tenerle al fresco)</li><li>[ ] Cubetti di formaggio o formaggio filante</li><li>[ ] Carne secca o essiccata</li><li>[ ] Snack di riserva</li></ul><p><strong>Più ti eserciti con questo kit, più diventerà automatico.</strong></p><h2 id="consigli-pratici" tabindex="-1">Consigli pratici <a class="header-anchor" href="#consigli-pratici" aria-label="Permalink to &quot;Consigli pratici&quot;">​</a></h2><h3 id="snack-facili-da-competizione" tabindex="-1">Snack facili da competizione <a class="header-anchor" href="#snack-facili-da-competizione" aria-label="Permalink to &quot;Snack facili da competizione&quot;">​</a></h3><ul><li>Frutta secca mista (non salata)</li><li>Uova sode</li><li>cubetti di formaggio</li><li>Carne secca di manzo o tacchino</li><li>Verdure con hummus</li><li>Olive</li></ul><h3 id="cosa-evitare" tabindex="-1">Cosa evitare <a class="header-anchor" href="#cosa-evitare" aria-label="Permalink to &quot;Cosa evitare&quot;">​</a></h3><ul><li>Snack da distributori automatici</li><li>Bevande sportive zuccherate</li><li>Pasticceria e prodotti da forno</li><li>Barrette di cioccolato e caramelle</li><li>La maggior parte delle barrette &quot;energetiche&quot; (controllare il contenuto di zucchero)</li></ul><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>Il cervello è lo strumento più importante nella pétanque. Offritegli un carburante stabile, non un&#39;energia da montagne russe. E allenate la vostra alimentazione proprio come vi allenate per il lancio: la ripetizione crea comfort e affidabilità.</p></blockquote><p>Concentratevi su proteine, grassi sani e sull&#39;idratazione. Evitate i picchi di zucchero. <strong>La cosa più importante: fate in modo che la vostra alimentazione per il giorno della gara sia la vostra alimentazione quotidiana.</strong> Il vostro corpo ha bisogno di allenamento per dare il massimo.</p><p><strong>Ricorda:</strong> Non ti presenteresti a un torneo con una tecnica di lancio che non hai mai provato. Non presentarti nemmeno con una strategia nutrizionale che non hai mai provato.</p>',52))])}]]);export{u as __pageData,p as default};
